<?php
namespace App\Controllers; use App\Core\{Controller,Database}; use App\Services\AuditLogger; class CrudController extends Controller{private array $allowed=['funds','users','payments','installments','transactions','notifications','documents']; public function index(string $table){if(!in_array($table,$this->allowed,true)){$this->json(['ok'=>false],404);} $rows=Database::pdo()->query('SELECT * FROM '.$table.' ORDER BY id DESC LIMIT 200')->fetchAll();$this->view('dashboard/table',['title'=>'مدیریت '.$table,'table'=>$table,'rows'=>$rows]);} public function store(string $table){$this->requireCsrf();if(!in_array($table,$this->allowed,true))$this->json(['ok'=>false],404);$d=$this->input();unset($d['_token']);$cols=array_keys($d);$sql='INSERT INTO '.$table.' (`'.implode('`,`',$cols).'`) VALUES ('.implode(',',array_fill(0,count($cols),'?')).')';$s=Database::pdo()->prepare($sql);$s->execute(array_values($d));$id=(int)Database::pdo()->lastInsertId();AuditLogger::log('create_'.$table,$table,$id);$this->json(['ok'=>true,'id'=>$id,'message'=>'با موفقیت ذخیره شد.']);} public function delete(string $table,int $id){$this->requireCsrf(); if($table==='ledger_entries'||$table==='ledger_lines')$this->json(['ok'=>false,'message'=>'اسناد دفتر کل غیرقابل حذف هستند.'],422);Database::pdo()->prepare('DELETE FROM '.$table.' WHERE id=?')->execute([$id]);AuditLogger::log('delete_'.$table,$table,$id);$this->json(['ok'=>true]);}}
